        if ("STANDARD".equals(ratePlan)) {
            refund = amountPaid;
        }

        try (Connection conn = db.getConnection();
             PreparedStatement stmt = conn.prepareStatement(
                     "UPDATE reservations SET status = ?, refund = ? WHERE id = ?")) {

