                    room.number,
                    room.type,
                    checkedOut.checkIn,
                    checkedOut.checkOut,
                    checkedOut.nights,
                    checkedOut.subtotal,
                    checkedOut.discount,
                    checkedOut.total
            );

            ctx.json(voucher);
        } catch (Exception e) {
            ctx.status(404);
            ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reserva não encontrada"));
        }
    }

